class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        return self.quick_select(nums, 0, len(nums) - 1, k - 1)

    def quick_select(self, nums, l, r, k):
      pivot = nums[l]
      if l == r:  return nums[k]
      i = l - 1
      j = r + 1
      while i < j:
        i += 1
        while nums[i] > pivot:
          i += 1
        j -= 1
        while nums[j] < pivot:
          j -=1 
        if i < j:
          nums[i], nums[j] =nums[j], nums[i]
      if k <= j:  return self.quick_select(nums, l, j, k)
      else: return self.quick_select(nums, j + 1, r, k)

class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        low = min(nums)
        high = max(nums)

        while low < high:
            mid = (low + high + 1) // 2
            have = sum(int(x >= mid) for x in nums)
            if have >= k:
                low = mid
            else:
                high = mid-1
        return low

