class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:


        def quick_select(left, right, k):
            if left > right:
                return None
            if left == right:
                return nums[left]

            pivot = nums[randint(left, right)]
            i = curr = left
            j = right
            while curr <= j:
                if nums[curr] > pivot:
                    nums[curr], nums[j] = nums[j], nums[curr]
                    j -= 1
                elif nums[curr] < pivot:
                    nums[curr], nums[i] = nums[i], nums[curr]
                    i += 1
                    curr += 1
                else:
                    curr += 1

            greater = right - (j+1) + 1
            greater_equal = right - i + 1
            if greater >= k:
                return quick_select(j+1, right, k)
            elif greater_equal >= k:
                return pivot
            else:
                return quick_select(left, i-1, k-greater_equal)



        n = len(nums)
        res = quick_select(0, n-1, k)
        return res

