        nodes = {} # this tells us the shortest distance to reach each node from the start node

        counter = 1
        while counter <= n:
            if counter == start_node:
                nodes[counter] = 0
            else:
                nodes[counter] = sys.maxsize
            counter += 1

        counter = 1

        while counter < n:

            for edge in edges:

                start = edge[0]
                end = edge[1]

                if nodes[start] != sys.maxsize:

                    weight = nodes[start] + edges[edge]

                    if weight < nodes[end]:
                        nodes[end] = weight
            counter += 1

        mx = 0

        for key in nodes:
            if nodes[key] > mx:
                mx = nodes[key]

        if mx == sys.maxsize:
            return -1
        return mx
