from collections import defaultdict
import sys , heapq
class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """
        dist = [sys.maxint]*(n+1)
        graph = defaultdict(list)
        for t in times :
            graph[t[0]].append([t[1] , t[2]])
        dist[k] = 0
        h = []
        spSet = set()
        heapq.heappush(h,(0,k))
        while len(h) > 0 :
            val , node = heapq.heappop(h)
            if node in spSet :
                continue
            spSet.add(node)
            for ele in graph[node] :
                if dist[ele[0]] > val+ele[1] :
                    dist[ele[0]] = val+ele[1]
                    heapq.heappush(h , (val+ele[1] , ele[0]))
        if len(spSet) < n :
            return -1
        else :
            return max(dist[1:])

class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """

        visited = set() 
        minHeap = [[0,k]] #[minDistance,node]
        res = 0
        while len(visited) < n:
            if len(minHeap) == 0:
                return -1
            else:
                minDistance, node = heapq.heappop(minHeap)
                if node not in visited:
                    visited.add(node)
                    res = max(res,minDistance)
                    for srcNode,destNode,dist in times:
                        if srcNode == node and destNode not in visited:
                            heapq.heappush(minHeap, [dist+minDistance,destNode] )
        return res

