            if x-1 < n and y < n and x-1>=0 and y>=0 and grid[x-1][y] == 0 and visited[x-1][y] == 0:
                queue.append([x-1,y,c+1])
            if x < n and y-1 < n and x>=0 and y-1>=0 and grid[x][y-1] == 0 and visited[x][y-1] == 0:
