        :type source: int
        :type destination: int
        :rtype: bool
        """
        map = defaultdict(list)
        for e in edges: 
            map[e[0]].append(e[1])
            map[e[1]].append(e[0])

        return self._rec(source, destination, map, set())


    def _rec(self, sour, dest, map, mem):
        if sour == dest:
            return True
        if sour in mem:
            return False

        mem.add(sour)

        result = False
        for n in map[sour]:
            result = result or self._rec(n, dest, map, mem)

        return result

