class Solution:
    def validPath(self, n, edges, source, destination):
        parent = [i for i in range(n)]
        def findRoot(x):
            if parent[x] != x:
                parent[x] = findRoot(parent[x])
            return parent[x]
        def union(a,b,parent):
            q = findRoot(a)
            m = findRoot(b)
            parent[q] = m
        for a,b in edges:
            union(a,b,parent)
        return findRoot(source) == findRoot(destination)

