def shortest_path(grid: List[List[int]]) -> int:
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        r, c, dist = queue.popleft()

        if r == rows - 1 and c == cols - 1:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == 0:
                queue.append((nr, nc, dist + 1))
                visited.add((nr, nc))

    return -1

def dfs_traversal(graph, start):
    stack = [start]
    visited = set()
    traversal_order = []

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            traversal_order.append(node)
            # Add adjacent nodes to stack (in reverse order to maintain correct traversal)
            for neighbor in reversed(graph[node]):
                if neighbor not in visited:
                    stack.append(neighbor)

    return traversal_order

import heapq

def trap_rain_water(elevation_map):
    if not elevation_map or not elevation_map[0]:
        return 0

    m, n = len(elevation_map), len(elevation_map[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Add all the boundary cells to the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (elevation_map[i][j], i, j))
                visited[i][j] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                water_trapped += max(0, height - elevation_map[nx][ny])
                heapq.heappush(heap, (max(height, elevation_map[nx][ny]), nx, ny))

    return water_trapped

