def find_shortest_path(edges: List[Tuple[int, int, float]], start_node: int, end_node: int) -> float:
    if start_node == end_node:
        return 0.0

    # Build the graph as an adjacency list
    graph = {}
    for node1, node2, weight in edges:
        if node1 not in graph:
            graph[node1] = []
        if node2 not in graph:
            graph[node2] = []
        graph[node1].append((weight, node2))
        graph[node2].append((weight, node1))

    # Dijkstra's algorithm
    priority_queue = [(0, start_node)]
    shortest_paths = {start_node: 0}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_node == end_node:
            return current_distance

        for weight, neighbor in graph.get(current_node, []):
            distance = current_distance + weight

            if neighbor not in shortest_paths or distance < shortest_paths[neighbor]:
                shortest_paths[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return float('inf')

from typing import List

def single_number3(nums: List[int]) -> List[int]:
    # Step 1: XOR all numbers to get the XOR of the two unique numbers
    xor = 0
    for num in nums:
        xor ^= num

    # Step 2: Find the right-most set bit of xor
    rightmost_set_bit = xor & -xor

    # Step 3: Divide numbers into two groups and XOR each group
    num1, num2 = 0, 0
    for num in nums:
        if num & rightmost_set_bit:
            num1 ^= num
        else:
            num2 ^= num

    return [num1, num2]

