def bellman_ford(graph, source):
    # Step 1: Initialize distances from source to all other nodes as infinity
    # and distance to source itself as 0.
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Step 2: Relax all edges |V| - 1 times.
    for i in range(len(graph) - 1):
        for node in graph:
            for neighbor in graph[node]:
                if distances[node] + graph[node][neighbor] < distances[neighbor]:
                    distances[neighbor] = distances[node] + graph[node][neighbor]

    # Step 3: Check for negative-weight cycles.
    for node in graph:
        for neighbor in graph[node]:
            if distances[node] + graph[node][neighbor] < distances[neighbor]:
                return {}

    return distances

import heapq

def shortest_path_with_constraints(roads, source, destination, blocked):
    # Create an adjacency list for graph representation
    graph = {}
    for u, v, t in roads:
        if (u, v) in blocked or (v, u) in blocked:
            continue
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, t))
        graph[v].append((u, t))

    # Use a priority queue to implement Dijkstra's algorithm
    pq = [(0, source)]  # (distance, node)
    distances = {source: 0}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node == destination:
            return current_distance

        if current_distance > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1

def find_needle_in_haystack(haystack: str, needle: str) -> int:
    """
    Implements the KMP algorithm to find the first occurrence of 'needle' in 'haystack'.
    Returns the starting index of 'needle' in 'haystack' or -1 if 'needle' is not found.
    """
    if not needle:
        return 0  # If the needle is an empty string, we return 0.

    n, m = len(haystack), len(needle)

    # Preprocess the needle to create the LPS array
    lps = [0] * m
    j = 0  # length of the previous longest prefix suffix
    i = 1
    while i < m:
        if needle[i] == needle[j]:
            j += 1
            lps[i] = j
            i += 1
        else:
            if j != 0:
                j = lps[j-1]
            else:
                lps[i] = 0
                i += 1

    # Start searching using the LPS array
    i = j = 0  # index for haystack and needle respectively
    while i < n:
        if needle[j] == haystack[i]:
            i += 1
            j += 1

        if j == m:
            return i - j  # match found

        elif i < n and needle[j] != haystack[i]:
            if j != 0:
                j = lps[j-1]
            else:
                i += 1

    return -1  # no match found

import heapq
from typing import Dict, List, Tuple

def shortest_path(graph: Dict[int, List[Tuple[int, int]]], start: int) -> Dict[int, int]:
    """
    Computes the shortest path from the start node to all other nodes using Dijkstra's algorithm.
    If a node is unreachable from the start node, its shortest distance is set to float('inf').
    """
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def bellman_ford(graph, source):
    """
    Implements the Bellman-Ford algorithm to detect negative-weight cycles
    in a graph and find the shortest path from a source node.

    Parameters:
    graph (dict): A dictionary representing the directed graph, with edge weights.
    source (str): The starting node.

    Returns:
    bool: True if no negative-weight cycles exist, False otherwise.
    """

    # Initialize distance to all vertices as infinite and distance to source as 0
    distance = {node: float('inf') for node in graph}
    distance[source] = 0

    # Relax edges |V|-1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                    distance[v] = distance[u] + graph[u][v]

    # Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                return False  # Negative cycle detected

    return True

def rabin_karp(word: str, text: str) -> int:
    if not word or not text or len(word) > len(text):
        return -1

    base = 256
    prime = 101
    m = len(word)
    n = len(text)

    hash_word = 0
    hash_text = 0
    h = 1

    for i in range(m - 1):
        h = (h * base) % prime

    for i in range(m):
        hash_word = (base * hash_word + ord(word[i])) % prime
        hash_text = (base * hash_text + ord(text[i])) % prime

    for i in range(n - m + 1):
        if hash_word == hash_text:
            if text[i:i + m] == word:
                return i

        if i < n - m:
            hash_text = (base * (hash_text - ord(text[i]) * h) + ord(text[i + m])) % prime
            if hash_text < 0:
                hash_text = hash_text + prime

    return -1

def rabin_karp_enhanced(pattern: str, text: str) -> int:
    """
    Finds the first occurrence of the pattern in the text using the Rabin-Karp algorithm.
    :param pattern: The substring to be searched.
    :param text: The text within which the pattern is to be searched.
    :return: The starting index of the first occurrence of the pattern in the text, or -1 if the pattern is not found.
    """
    if len(pattern) > len(text):
        return -1

    base = 256  # Number of characters in the input alphabet
    prime = 101  # A prime number to use for hashing

    pattern_length = len(pattern)
    text_length = len(text)

    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(pattern_length - 1):
        h = (h * base) % prime

    for i in range(pattern_length):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(text_length - pattern_length + 1):
        if pattern_hash == text_hash:
            if text[i:i + pattern_length] == pattern:
                return i

        if i < text_length - pattern_length:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + pattern_length])) % prime

            if text_hash < 0:
                text_hash += prime

    return -1

from collections import deque

def shortest_path(graph, start, end):
    """
    Find the shortest path between start and end nodes in an unweighted graph.
    """
    if start not in graph or end not in graph:
        return []

    queue = deque([start])
    predecessors = {start: None}

    while queue:
        current = queue.popleft()
        if current == end:
            break
        for neighbor in graph[current]:
            if neighbor not in predecessors:
                queue.append(neighbor)
                predecessors[neighbor] = current

    if end not in predecessors:
        return []

    path = []
    curr_node = end
    while curr_node is not None:
        path.append(curr_node)
        curr_node = predecessors[curr_node]
    path.reverse()

    return path

def is_strictly_increasing(lst):
    """
    Returns True if the list 'lst' is strictly increasing, False otherwise.
    """
    # An empty list or a list with a single element is considered strictly increasing
    if len(lst) <= 1:
        return True

    # Iterate over the list and check if each element is strictly
    # greater than the previous one
    for i in range(1, len(lst)):
        if lst[i] <= lst[i - 1]:
            return False
    return True

